import sys
import base64
import json
import time
from json.decoder import JSONDecodeError

def main():
    if len(sys.argv) != 5:
        print("Usage: python access_check.py <username> <resource> <token_file> <rules_file>", file=sys.stderr)
        sys.exit(1)

    username = sys.argv[1]
    resource = sys.argv[2]
    token_file = sys.argv[3]
    rules_file = sys.argv[4]

    try:
        with open(token_file, 'rb') as f:
            token_bytes = f.read()
            token_data = base64.b64decode(token_bytes)
            token_json = json.loads(token_data)
            if 'sub' not in token_json or 'role' not in token_json or 'exp' not in token_json:
                print("ERROR: Invalid token structure", file=sys.stderr)
                sys.exit(2)
            if token_json['exp'] <= time.time():
                print("ERROR: Token expired", file=sys.stderr)
                sys.exit(2)
    except JSONDecodeError:
        print("ERROR: Invalid token", file=sys.stderr)
        sys.exit(2)
    except Exception as e:
        print(f"ERROR: Failed to decode token: {str(e)}", file=sys.stderr)
        sys.exit(2)

    user = {'name': username, 'role': token_json['role']}

    with open(rules_file, 'r') as f:
        for line_num, line in enumerate(f, 1):
            stripped_line = line.strip()
            if not stripped_line or stripped_line.startswith('#'):
                continue
            try:
                if eval(f"user, resource\n{stripped_line}", {'user': user, 'resource': resource}):
                    print(f"ALLOW: {stripped_line}")
                    sys.exit(0)
            except Exception as e:
                print(f"ERROR: {stripped_line}: {str(e)}", file=sys.stderr)

    print("DENY")
    sys.exit(1)

if __name__ == "__main__":
    main()

