import sys
import base64
import json
import time
import ast

def validate_token(token_file):
    try:
        with open(token_file, 'rb') as f:
            token_bytes = f.read()
            token_data = base64.b64decode(token_bytes).decode('utf-8')
            token_obj = json.loads(token_data)
            if 'sub' not in token_obj or 'role' not in token_obj or 'exp' not in token_obj:
                return False, "Missing required fields in token"
            current_time = int(time.time())
            if current_time >= token_obj['exp']:
                return False, "Token expired"
            return True, token_obj
    except (base64.binascii.Error, json.JSONDecodeError, IOError) as e:
        return False, f"Token decoding error: {str(e)}"

def evaluate_rules(rules_file, user, resource):
    with open(rules_file) as f:
        for line_num, line in enumerate(f, 1):
            stripped_line = line.strip()
            if not stripped_line or stripped_line.startswith('#'):
                continue
            try:
                expr = ast.literal_eval(stripped_line)
                if isinstance(expr, ast.Expression):
                    code = compile(expr.body, '<string>', 'eval')
                    result = eval(code, {'user': user, 'resource': resource}, {})
                    if result:
                        print(f"ALLOW: {stripped_line}")
                        sys.exit(0)
            except Exception as e:
                print(f"ERROR: {stripped_line}: {str(e)}", file=sys.stderr)
    print("DENY")
    sys.exit(1)

def main():
    if len(sys.argv) != 5:
        print("Usage: python access_check.py <username> <resource> <token_file> <rules_file>", file=sys.stderr)
        sys.exit(2)

    username = sys.argv[1]
    resource = sys.argv[2]
    token_file = sys.argv[3]
    rules_file = sys.argv[4]

    is_valid, token_data = validate_token(token_file)
    if not is_valid:
        print(f"ERROR: {token_data}", file=sys.stderr)
        sys.exit(2)

    user = {'name': username, 'role': token_data['role']}
    evaluate_rules(rules_file, user, resource)

if __name__ == "__main__":
    main()
